choose.when:
select 'row' as level, item_key as item_key, max(note_no) as note_no, max(case when side = 'PDF' then concat(coalesce(table_title, '默认表'), ' / 行') end) as pdf_title, max(case when side = 'PDF' then coalesce(nullif(row_path, ''), nullif(row_leaf, ''), row_key) end) as pdf_detail, max(case when side = 'PDF' then source_locator end) as pdf_locator, max(case when side = 'EXCEL' then concat(coalesce(table_title, '默认表'), ' / 行') end) as excel_title, max(case when side = 'EXCEL' then coalesce(nullif(row_path, ''), nullif(row_leaf, ''), row_key) end) as excel_detail, max(case when side = 'EXCEL' then source_locator end) as excel_locator, false as runtime_recognized, 'MISSING' as runtime_status, null as runtime_title, '当前还没有导入 runtime 结构，先按未识别展示' as runtime_detail, null as runtime_locator from structure_row where project_id = #{projectId} and note_no = #{noteNo}
and ( table_title like concat('%', #{keyword}, '%') or row_key like concat('%', #{keyword}, '%') or row_path like concat('%', #{keyword}, '%') or row_leaf like concat('%', #{keyword}, '%') or source_locator like concat('%', #{keyword}, '%') )
group by item_key order by item_key

select 'column' as level, item_key as item_key, max(note_no) as note_no, max(case when side = 'PDF' then concat(coalesce(table_title, '默认表'), ' / 列名') end) as pdf_title, max(case when side = 'PDF' then coalesce(nullif(column_path, ''), nullif(column_leaf, ''), column_key) end) as pdf_detail, max(case when side = 'PDF' then source_locator end) as pdf_locator, max(case when side = 'EXCEL' then concat(coalesce(table_title, '默认表'), ' / 列名') end) as excel_title, max(case when side = 'EXCEL' then coalesce(nullif(column_path, ''), nullif(column_leaf, ''), column_key) end) as excel_detail, max(case when side = 'EXCEL' then source_locator end) as excel_locator, false as runtime_recognized, 'MISSING' as runtime_status, null as runtime_title, '当前还没有导入 runtime 结构，先按未识别展示' as runtime_detail, null as runtime_locator from structure_column where project_id = #{projectId} and note_no = #{noteNo}
and ( table_title like concat('%', #{keyword}, '%') or column_key like concat('%', #{keyword}, '%') or column_path like concat('%', #{keyword}, '%') or column_leaf like concat('%', #{keyword}, '%') or source_locator like concat('%', #{keyword}, '%') )
group by item_key order by item_key

choose.otherwise:
select 'cell' as level, item_key as item_key, max(note_no) as note_no, max(case when side = 'PDF' then concat(coalesce(table_title, '默认表'), ' / 单元格') end) as pdf_title, max(case when side = 'PDF' then concat('行：', coalesce(nullif(row_path, ''), row_key, '未命名行'), '；列：', coalesce(nullif(column_path, ''), column_key, '未命名列'), '；值：', coalesce(nullif(value_text, ''), normalized_value, '空值')) end) as pdf_detail, max(case when side = 'PDF' then source_locator end) as pdf_locator, max(case when side = 'EXCEL' then concat(coalesce(table_title, '默认表'), ' / 单元格') end) as excel_title, max(case when side = 'EXCEL' then concat('行：', coalesce(nullif(row_path, ''), row_key, '未命名行'), '；列：', coalesce(nullif(column_path, ''), column_key, '未命名列'), '；值：', coalesce(nullif(value_text, ''), normalized_value, '空值')) end) as excel_detail, max(case when side = 'EXCEL' then source_locator end) as excel_locator, false as runtime_recognized, 'MISSING' as runtime_status, null as runtime_title, '当前还没有导入 runtime 结构，先按未识别展示' as runtime_detail, null as runtime_locator from structure_cell where project_id = #{projectId} and note_no = #{noteNo}
and ( table_title like concat('%', #{keyword}, '%') or row_key like concat('%', #{keyword}, '%') or row_path like concat('%', #{keyword}, '%') or column_key like concat('%', #{keyword}, '%') or column_path like concat('%', #{keyword}, '%') or value_text like concat('%', #{keyword}, '%') or normalized_value like concat('%', #{keyword}, '%') or source_locator like concat('%', #{keyword}, '%') )
group by item_key order by item_key
